import{_ as e,o as a,c as n,a2 as i}from"./chunks/framework.CWWEQfK7.js";const u=JSON.parse('{"title":"Set up local development","description":"Prepare dependencies, infrastructure, and processes for six independent repositories, then verify the environment layer by layer.","frontmatter":{"page_id":"development-local-setup","title":"Set up local development","description":"Prepare dependencies, infrastructure, and processes for six independent repositories, then verify the environment layer by layer."},"headers":[],"relativePath":"en/development/local-setup.md","filePath":"en/development/local-setup.md","lastUpdated":1786290726000}'),t={name:"en/development/local-setup.md"};function l(r,s,p,o,d,h){return a(),n("div",null,[...s[0]||(s[0]=[i(`<h1 id="set-up-local-development" tabindex="-1">Set up local development <a class="header-anchor" href="#set-up-local-development" aria-label="Permalink to &quot;Set up local development&quot;">​</a></h1><p>The complete development setup currently targets maintainers who can access Ershu&#39;s private component sources. Backend lockfiles refer to private Git locations, so cloning only the public composition repository is not sufficient. Do not replace locked dependencies with unpinned sibling directories.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Python 3.14 or later;</li><li>UV for installing and running Python projects;</li><li>Node.js 24 and npm for the frontend;</li><li>Docker and Docker Compose for PostgreSQL, Redis, and Milvus;</li><li>SSH credentials that can read the component sources in the lockfiles;</li><li>matching revisions of the five modules and the <code>ershu</code> composition repository.</li></ul><p>Keep the source as six sibling directories rather than nesting everything into a monorepo:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>workspace/</span></span>
<span class="line"><span>├── ershu/</span></span>
<span class="line"><span>├── core/</span></span>
<span class="line"><span>├── api/</span></span>
<span class="line"><span>├── worker/</span></span>
<span class="line"><span>├── mcp/</span></span>
<span class="line"><span>└── frontend/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>Each directory has its own branch, manifest, and history. Run <code>git status --short --branch</code> in every repository and account for uncommitted work before continuing.</p><h2 id="start-the-complete-backend-from-the-composition-repository" tabindex="-1">Start the complete backend from the composition repository <a class="header-anchor" href="#start-the-complete-backend-from-the-composition-repository" aria-label="Permalink to &quot;Start the complete backend from the composition repository&quot;">​</a></h2><p>Run these commands in a Bash shell from <code>ershu</code>. Replace every sample security value after copying the files.</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.compose.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.compose</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><code>.env.compose</code> supplies PostgreSQL and MinIO credentials. <code>.env</code> supplies database, Redis, Milvus, session, encryption, MCP, and Worker settings. Values such as <code>replace-me</code>, fixed weak passwords, and empty production requirements are not usable configuration.</p><p>Start infrastructure:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>PostgreSQL, Redis, Milvus, etcd, and MinIO should start, and services with health checks should eventually report healthy. If they do not, inspect <code>docker compose --env-file .env.compose logs</code> before attempting a migration.</p><p>Install the locked backend combination and upgrade the database:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all-extras</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> heads</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> head</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><code>ershu-db heads</code> should discover the migration records packaged with Core. After the upgrade succeeds, open separate terminals for the processes:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Terminal A</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-api</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Terminal B</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-mcp</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Terminal C</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-worker</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Terminal D; only needed for scheduled polling</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-api-poller</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>API listens on <code>127.0.0.1:8000</code> by default and MCP on <code>127.0.0.1:8001</code>. Confirm that the HTTP processes respond:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8000/health</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8001/health</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Both should return a <code>status</code> of <code>ok</code>. This is liveness only; it does not prove business readiness for the database, Milvus, model channels, or Worker.</p><h2 id="start-the-frontend" tabindex="-1">Start the frontend <a class="header-anchor" href="#start-the-frontend" aria-label="Permalink to &quot;Start the frontend&quot;">​</a></h2><p>In the separate <code>frontend</code> directory, run:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.local</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>The development server uses <code>http://localhost:3000</code>. It proxies <code>/api</code> to <code>http://localhost:8000</code> and <code>/mcp</code> to <code>http://127.0.0.1:8001</code> by default. If the services use different addresses, change only the corresponding development proxy variables in <code>.env.local</code>.</p><p>Open <code>http://localhost:3000/#/zh/setup-admin</code> for the first visit. With no user present, it starts first-admin setup; after success, it proceeds to login or the project workspace. Ershu has no public self-registration. Administrators create later accounts.</p><h2 id="work-on-one-backend-module" tabindex="-1">Work on one backend module <a class="header-anchor" href="#work-on-one-backend-module" aria-label="Permalink to &quot;Work on one backend module&quot;">​</a></h2><p>Install from that repository&#39;s lockfile without injecting source from another module into the import path:</p><table tabindex="0"><thead><tr><th>Module</th><th>Install</th><th>Minimum verification</th></tr></thead><tbody><tr><td>Core</td><td><code>uv sync --frozen</code></td><td><code>uv run pytest -m &quot;not integration&quot;</code></td></tr><tr><td>API</td><td><code>uv sync --extra dev --frozen</code></td><td><code>uv run --extra dev pytest -q</code></td></tr><tr><td>Worker</td><td><code>uv sync --extra dev --frozen</code></td><td><code>uv run pytest -q</code></td></tr><tr><td>MCP</td><td><code>uv sync --frozen</code></td><td><code>uv run pytest -q</code></td></tr></tbody></table><p>The Core, API, Worker, and MCP lockfiles pin compatible Core revisions. After changing Core, commit it and update the consuming dependency and lockfile before cross-repository acceptance work.</p><h2 id="verify-that-the-environment-is-useful" tabindex="-1">Verify that the environment is useful <a class="header-anchor" href="#verify-that-the-environment-is-useful" aria-label="Permalink to &quot;Verify that the environment is useful&quot;">​</a></h2><p>Check from the nearest dependency outward:</p><ol><li>Infrastructure containers are healthy and the database is at the current head.</li><li>API and MCP liveness endpoints return <code>ok</code>.</li><li>The frontend opens and completes first-admin setup.</li><li>The administrator creates and tests a model channel.</li><li>A test repository can be added and validated.</li><li>A full-project run moves from queued to running and reaches an explicit outcome.</li><li>Completed documents open and search returns source locations.</li></ol><p>Stop at the first failed layer. If processes are alive but a run remains queued, check the Worker first. If document generation fails, inspect the model channel. If semantic retrieval fails, inspect Milvus and embedding settings.</p><blockquote><p>Sources: manifests, lockfiles, README files, process entry points, Compose configuration, health routes, and CI across all six repositories.</p></blockquote>`,35)])])}const k=e(t,[["render",l]]);export{u as __pageData,k as default};
